      {
       "mota": "testua",
       "html": "Izan bitez <math display=\"inline\"><mi>V</mi></math> dimentsio finituko <math display=\"inline\"><mtext mathvariant=\"normal\">IK</mtext></math> espazio bektoriala eta <math display=\"inline\"><mrow><mi>W</mi><mo>≤</mo><mi>V</mi></mrow></math>. Orduan <math display=\"inline\"><mi>W</mi></math> azpiespazio bektorialak betegarri bat du."
      }
